def tint(t):
    """Room light colour multiplier: morning warm, storm cool/dim, sunset gold."""
    a = ease(seg(t, 20.5, 25.0))
    b = ease(seg(t, 28.5, 36.0))
    morning = (1.0, 0.98, 0.94)
    storm = (0.72, 0.76, 0.84)
    gold = (1.05, 0.86, 0.70)
    return mix(mix(morning, storm, a), gold, b)


